#!/usr/bin/env python3
"""Generate credited literature benchmarks for larger-order searches.

The odd construction is transcribed from Haselman, Rockwell, Eilers, Marks,
2025: https://www.jstor.org/stable/community.42242816 (one-page poster).
Its general counting formula is listed as a conjecture on that poster.
This program evaluates concrete instances; it does not assume the formula.
"""
import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from tools.rotation_counter import count_stable
from tools.constraint_counter import count_stable as independent_count

ODD_SOURCE = 'https://www.jstor.org/stable/community.42242816'
ODD_COUNTS = {3: 3, 5: 16, 7: 81, 9: 388, 11: 1790, 13: 8048, 15: 35525, 17: 154684, 19: 666498}


def from_ranks(mrank, wrank):
    n = len(mrank)
    return ([sorted(range(n), key=lambda w: mrank[m][w]) for m in range(n)],
            [sorted(range(n), key=lambda m: wrank[w][m]) for w in range(n)])


def odd_near_latin(n):
    """The 2025 poster's alternating men's rows and near-Latin women's rows."""
    if n < 3 or n % 2 == 0:
        raise ValueError('The odd construction requires odd n >= 3')
    mrank = [[(m + (1 if m % 2 == 0 else -1) * w) % n for w in range(n)] for m in range(n)]
    wrank = [[((n - 1 - m - 2 * ((w + 1) // 2)) % (n + 1)
               if m % 2 == 0 else (n - 1 - m + 2 * (w // 2)) % (n - 1))
              for m in range(n)] for w in range(n)]
    return from_ranks(mrank, wrank)


def group_latin(n):
    """Standard XOR, dihedral, or D6 x C2 Latin group-table benchmarks."""
    if n < 2 or n % 2:
        raise ValueError('Group benchmark requires even n >= 2')

    def dihedral_rank(order, m, w):
        return 2 * ((w // 2 + (1 if w % 2 == 0 else -1) * (m // 2)) % (order // 2)) + ((m % 2) ^ (w % 2))

    if n & (n - 1) == 0:
        mrank = [[m ^ w for w in range(n)] for m in range(n)]
    elif n == 12:
        mrank = [[2 * dihedral_rank(6, m // 2, w // 2) + ((m % 2) ^ (w % 2))
                  for w in range(n)] for m in range(n)]
    else:
        mrank = [[dihedral_rank(n, m, w) for w in range(n)] for m in range(n)]
    wrank = [[n - 1 - mrank[m][w] for m in range(n)] for w in range(n)]
    return from_ranks(mrank, wrank)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--family', choices=['odd-2025', 'group'], required=True)
    parser.add_argument('--order', type=int, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    mp, wp = odd_near_latin(args.order) if args.family == 'odd-2025' else group_latin(args.order)
    count = count_stable(mp, wp)
    checked = independent_count(mp, wp)
    if count != checked:
        raise AssertionError('Independent counters disagree')
    if args.family == 'odd-2025' and args.order in ODD_COUNTS and count != ODD_COUNTS[args.order]:
        raise AssertionError('Transcription disagrees with the published poster')
    witness = {
        'id': f'{args.family}-n{args.order}', 'order': args.order, 'expected_count': count,
        'men_preferences': mp, 'women_preferences': wp,
        'source': ODD_SOURCE if args.family == 'odd-2025' else 'Standard Latin group tables; https://oeis.org/A351413',
        'verification': {'rotation_count': count, 'blocking_constraint_count': checked},
    }
    artifact = {'format_version': 1, 'preference_format': 'best-first, zero-based partner labels', 'witnesses': [witness]}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open('x') as stream:
        stream.write(json.dumps(artifact, indent=2) + '\n')
    print(f'{witness["id"]}: {count} stable matchings; independent counters agree')


if __name__ == '__main__':
    main()

