"""Independent seed polynomial via complete blocking-constraint enumeration.

This module never imports a global rotation extractor or poset counter. It
enumerates stable matchings directly, then counts cycles of the successor
map at each matching. With all cycles of size two, these coefficients are
the antichain polynomial needed by the iterated doubling theorem.
"""


class EnumerationLimit(RuntimeError):
    pass


def exposed_cycles(mpref, wpref, matching):
    n = len(mpref)
    mr = [{w: i for i, w in enumerate(row)} for row in mpref]
    wr = [{m: i for i, m in enumerate(row)} for row in wpref]
    inverse = {w: m for m, w in enumerate(matching)}
    following = []
    for m in range(n):
        following.append(next((inverse[w] for w in mpref[m][mr[m][matching[m]] + 1:]
                               if wr[w][m] < wr[w][inverse[w]]), None))
    completed, cycles = set(), []
    for start in range(n):
        visited, path, m = {}, [], start
        while m is not None and m not in completed and m not in visited:
            visited[m] = len(path)
            path.append(m)
            m = following[m]
        if m in visited:
            cycles.append(tuple(path[visited[m]:]))
        completed.update(path)
    return cycles


def stable_assignments(mpref, wpref, max_states=2000000):
    """Generate every stable assignment with direct pairwise forward checking."""
    n = len(mpref)
    if n < 1 or len(wpref) != n or any(sorted(row) != list(range(n))
                                      for table in (mpref, wpref) for row in table):
        raise ValueError('Expected complete strict preferences')
    mr = [{w: i for i, w in enumerate(row)} for row in mpref]
    wr = [{m: i for i, m in enumerate(row)} for row in wpref]

    def propose(pref, other):
        held = {}
        for start in range(n):
            free = start
            while free is not None:
                for target in pref[free]:
                    old = held.get(target)
                    if old is None or other[target][free] < other[target][old]:
                        held[target], free = free, old
                        break
        return held

    man_opt = propose(mpref, wr)
    woman_opt = propose(wpref, mr)
    best_m = {m: w for w, m in man_opt.items()}
    best_w = {w: m for m, w in woman_opt.items()}
    domains = [set(w for w in range(n)
                   if mr[m][best_m[m]] <= mr[m][w] <= mr[m][woman_opt[m]]
                   and wr[w][best_w[w]] <= wr[w][m] <= wr[w][man_opt[w]]) for m in range(n)]
    compatible = {}
    for m in range(n):
        for w in domains[m]:
            for other in range(n):
                if other == m:
                    continue
                compatible[m, w, other] = set(partner for partner in domains[other]
                    if partner != w
                    and not (mr[m][partner] < mr[m][w] and wr[partner][m] < wr[partner][other])
                    and not (mr[other][w] < mr[other][partner] and wr[w][other] < wr[w][m]))
    matching = [-1] * n
    states = 0

    def visit(remaining):
        nonlocal states
        states += 1
        if states > max_states:
            raise EnumerationLimit('Independent matching enumeration exceeded its state budget')
        if not remaining:
            yield tuple(matching)
            return
        m = min(remaining, key=lambda person: (len(remaining[person]), person))
        for w in sorted(remaining[m]):
            next_domains = {other: options & compatible[m, w, other]
                            for other, options in remaining.items() if other != m}
            if all(next_domains.values()):
                matching[m] = w
                yield from visit(next_domains)
                matching[m] = -1

    yield from visit({m: options for m, options in enumerate(domains)})


def frontier_polynomial(mpref, wpref, max_matchings=200000, max_states=2000000):
    coefficients, sizes, total = [], set(), 0
    for matching in stable_assignments(mpref, wpref, max_states):
        total += 1
        if total > max_matchings:
            raise EnumerationLimit('Independent frontier matching budget exceeded')
        cycles = exposed_cycles(mpref, wpref, matching)
        sizes.update(map(len, cycles))
        while len(coefficients) <= len(cycles):
            coefficients.append(0)
        coefficients[len(cycles)] += 1
    return {'stable_count': total, 'coefficients': coefficients,
            'exposed_rotation_sizes': sorted(sizes), 'all_rotations_size_two': sizes <= {2}}

